import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"CLI","description":"kirivers server 与 admin add|delete|list|reset-password|clear-2fa。没有 listen 子命令。","frontmatter":{"title":"CLI","description":"kirivers server 与 admin add|delete|list|reset-password|clear-2fa。没有 listen 子命令。"},"headers":[],"relativePath":"guide/cli.md","filePath":"guide/cli.md","lastUpdated":1790057721000}`),a={name:`guide/cli.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to “CLI”">​</a></h1><p>可执行文件入口等价于 <code>kirivers</code>。无位置参数时启动 HTTP 服务（与 <code>kirivers server</code> 相同）。</p><div class="language-text line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>KiriVers — unified startup entry</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Usage:</span></span>
<span class="line"><span>  kirivers [server] [-config path]                              start the HTTP servers (default)</span></span>
<span class="line"><span>                                                                client plane ... on client.yaml addr (:8080)</span></span>
<span class="line"><span>                                                                admin plane ... on admin.yaml addr (:8081)</span></span>
<span class="line"><span>  kirivers admin add &lt;username&gt; [-password secret]              create an instance admin</span></span>
<span class="line"><span>  kirivers admin delete &lt;username&gt;                              delete an instance admin</span></span>
<span class="line"><span>  kirivers admin list                                           list instance admins</span></span>
<span class="line"><span>  kirivers admin reset-password &lt;username&gt; [-password secret]   reset an admin password</span></span>
<span class="line"><span>  kirivers admin clear-2fa &lt;username&gt;                           clear TOTP, passkeys and recovery codes (does not revoke sessions)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p><strong>没有</strong> <code>kirivers listen</code> 子命令。仓库里的 <code>cmd/listen.go</code> 只用于 TLS 监听判定，不是 CLI。</p><h2 id="配置路径" tabindex="-1">配置路径 <a class="header-anchor" href="#配置路径" aria-label="Permalink to “配置路径”">​</a></h2><table tabindex="0"><thead><tr><th>来源</th><th>优先级</th></tr></thead><tbody><tr><td><code>-config path</code></td><td>最高</td></tr><tr><td>环境变量 <code>KIRIVERS_CONFIG</code></td><td><code>-config</code> 缺省时</td></tr><tr><td>默认 <code>configs/</code> 然后当前目录</td><td>都未指定时</td></tr></tbody></table><p><code>path</code> 可以是文件或目录。目录：该文件夹内的 <code>config.yaml</code> + <code>admin.yaml</code> + <code>client.yaml</code>。文件：该系统 YAML，加上同目录的 <code>admin.yaml</code> 与 <code>client.yaml</code>。缺文件时回退同目录 <code>*-example.yaml</code>。</p><p><code>kirivers admin</code> <strong>只加载系统 <code>config.yaml</code></strong>（库连接），不读 <code>admin.yaml</code>。</p><p><code>-password</code> 仅属于 <code>admin</code>。传给 <code>server</code> 时以退出码 <strong>2</strong> 打印用法。</p><p>工作目录：以下示例均假设当前目录已有三份 YAML，或已传 <code>-config</code>。</p><h2 id="kirivers-kirivers-server" tabindex="-1"><code>kirivers</code> / <code>kirivers server</code> <a class="header-anchor" href="#kirivers-kirivers-server" aria-label="Permalink to “kirivers / kirivers server”">​</a></h2><div class="language-bash line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kirivers</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./configs</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>成功：进程不退出；日志出现客户端与管理平面监听地址。失败：配置/日志双 sink 全关、PostgreSQL 连不上、<code>cache.driver=redis</code> 且 Ping 失败 → 非 0 退出且不监听。</p><p>常见错误：把 <code>-password</code> 传给 server → stderr 含 <code>-password is only valid with the admin command</code>，退出码 2。</p><h2 id="kirivers-admin-add" tabindex="-1"><code>kirivers admin add</code> <a class="header-anchor" href="#kirivers-admin-add" aria-label="Permalink to “kirivers admin add”">​</a></h2><div class="language-bash line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kirivers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> admin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>未传 <code>-password</code> 时在终端提示输入并确认密码。成功 stdout：</p><div class="language-text line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>created alice (&lt;uuid&gt;)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="kirivers-admin-list" tabindex="-1"><code>kirivers admin list</code> <a class="header-anchor" href="#kirivers-admin-list" aria-label="Permalink to “kirivers admin list”">​</a></h2><div class="language-bash line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kirivers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> admin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-text line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>USERNAME  ID                                    CREATED_AT</span></span>
<span class="line"><span>alice     11111111-1111-1111-1111-111111111111  2026-09-19T04:00:00Z</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="kirivers-admin-reset-password" tabindex="-1"><code>kirivers admin reset-password</code> <a class="header-anchor" href="#kirivers-admin-reset-password" aria-label="Permalink to “kirivers admin reset-password”">​</a></h2><div class="language-bash line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kirivers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> admin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset-password</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -password</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;new-secret&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>成功：<code>password reset for alice</code></p><h2 id="kirivers-admin-clear-2fa" tabindex="-1"><code>kirivers admin clear-2fa</code> <a class="header-anchor" href="#kirivers-admin-clear-2fa" aria-label="Permalink to “kirivers admin clear-2fa”">​</a></h2><div class="language-bash line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kirivers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> admin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clear-2fa</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>成功：<code>cleared 2FA for alice</code></p><p>清除 TOTP、Passkey 与恢复码。<strong>不</strong>吊销已有管理会话。操作者仍须用新密码或重新绑定 2FA 才能新登录。</p><h2 id="kirivers-admin-delete" tabindex="-1"><code>kirivers admin delete</code> <a class="header-anchor" href="#kirivers-admin-delete" aria-label="Permalink to “kirivers admin delete”">​</a></h2><div class="language-bash line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kirivers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> admin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> delete</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>成功：<code>deleted alice</code>。删除最后一名管理员会失败（<code>LAST_ADMIN</code>）。</p><p>未知子命令或缺用户名：退出码 2，并打印用法。</p>`,32)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};